import type { SourceSet } from '../types';
import { PAPER1_SOURCE_TEXT } from './paper1Sources.generated';

/**
 * Built-in History Paper 1 sets (prescribed subject 3) on real primary sources. Source texts are
 * verbatim excerpts generated by scripts/paper1_sources.py; origins, questions and mark-scheme
 * notes are written for the app. The schemes list points a good answer may make; they are not
 * official markschemes.
 */

const src = (key: keyof typeof PAPER1_SOURCE_TEXT & string, origin: string) => {
  const s = PAPER1_SOURCE_TEXT[key];
  if (!s) throw new Error(`Missing Paper 1 source ${key}`);
  return { origin, text: s.text, url: s.url };
};

/** A visual source: the image is shipped in public/sources/ and `text` describes it. */
const img = (src: string, text: string, origin: string, credit: string, url: string) => ({ origin, text, url, image: { src, credit } });

